def read_frame(stream):
    header = stream.read(4)
    if len(header) != 4:
        raise EOFError('truncated header')
    size = int.from_bytes(header, 'big')
    payload = stream.read(size)
    if len(payload) != size:
        raise EOFError('truncated payload')
    return payload

