class UserRegistry:
    def __init__(self): self._users={}
    def register(self, name):
        if name in self._users: raise ValueError('duplicate')
        self._users[name]={'display_name': name}
    def __contains__(self, name): return name in self._users
    def get(self, name): return self._users[name]

