import unittest
from signing import sign, verify

class SigningTests(unittest.TestCase):
    def test_roundtrip(self):
        key=b'k'; payload={'a':1,'b':2}
        self.assertTrue(verify(key,payload,sign(key,payload)))
    def test_change_fails(self):
        key=b'k'; sig=sign(key,{'a':1})
        self.assertFalse(verify(key,{'a':2},sig))

